def _next_recursive(recursive: bool | int) -> bool | int:
    """
    Compute the recursion flag for the next nested walk step.

    :param recursive: Current recursion mode. ``True`` means unlimited
        recursion, ``False`` means a single step only, and integers count the
        remaining recursion depth.
    :returns: The recursion mode that should be forwarded to the next nested
        instruction.
    :raises ValueError: If an integer recursion count is negative.
    :raises TypeError: If ``recursive`` is neither ``bool`` nor ``int``.
    """
    if isinstance(recursive, bool):
        if recursive is True:
            return True
        assert (
            False
        ), "you should not be here. You forgot to implement _interpret_recursive"
    elif isinstance(recursive, int):
        if recursive < 0:
            raise ValueError(
                "Number of recursive executions must be non-negative."
            )
        return recursive - 1
    raise TypeError(
        "The recursive argument must be a boolean or a non-negative integer."
    )


def _interpret_recursive(recursive: bool | int) -> bool | int:
    """
    Normalize a recursion flag into the value used by ``walk`` helpers.

    :param recursive: Requested recursion mode. ``True`` means unlimited
        recursion, ``False`` is normalized to a single recursion step, and an
        integer expresses the remaining explicit recursion depth.
    :returns: The normalized recursion marker.
    :raises ValueError: If an integer recursion count is negative.
    :raises TypeError: If ``recursive`` is neither ``bool`` nor ``int``.
    """
    if isinstance(recursive, bool):
        if recursive is True:
            return True
        # False is treated as a single recursion
        return 1
    elif isinstance(recursive, int):
        if recursive < 0:
            raise ValueError(
                "Number of recursive executions must be non-negative."
            )
        return recursive
    raise TypeError(
        "The recursive argument must be a boolean or a non-negative integer."
    )


