class Instruction:
    """Base class for all instruction nodes.

    Instructions form a tree that is later lowered into backend-specific code.
    Each node exposes a functional type via :attr:`ftype` and an implementation
    type via :attr:`itype`, plus traversal helpers used by environments and
    grouped instructions.
    """

    _ftype = "instruction"
    _obj_id_count = 0

    def _get_obj_id(self) -> str:
        """Return the next unique identifier for this concrete subclass."""
        type(self)._obj_id_count += 1
        return f"{self._ftype}#{type(self)._obj_id_count}"

    def _instruction_hash(self, generating: Any) -> int:
        """
        Create the stable hash used by :meth:`checksum`.

        :param generating: Hashable payload that uniquely represents the
            current instruction state.
        :returns: Hash value derived from ``generating``.
        """
        return stable_checksum(generating)

    @staticmethod
    def _get_itype_common_root(instruction_list: List[Instruction]) -> str:
        """
        Derive the longest common ``itype`` prefix shared by a list of
        instructions.

        :param instruction_list: Instructions whose implementation types should
            be compared.
        :returns: The common ``itype`` prefix, or an empty string if the input
            list is empty.
        """
        if len(instruction_list) == 0:
            return ""
        segments_list = [instr.itype.split(".") for instr in instruction_list]
        latest_parent_itype = ".".join(segment_overlap(*segments_list))
        return latest_parent_itype

    def __str__(self):
        return f"<{self.identifier}>"

    def __repr__(self):
        return f"<{self.identifier}>"

    def __len__(self) -> int:
        """
        Return the length of the instruction

        :returns: instruction length
        """
        return 1

    def to_dict(
        self, *keys: str, defaults: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        """
        Materialize the instruction as a dictionary.

        :param keys: Optional subset of keys to extract. If omitted, the full
            dictionary contributed by the class hierarchy is returned.
        :param defaults: Optional fallback mapping used when a requested key is
            not present on the instruction.
        :returns: Dictionary representation of the instruction.
        """
        if defaults is None:
            defaults = {}
        # check params first, then check defaults, return None for miss
        data_dict = {}  # _PartialFormatDict
        provided = {}
        for cls in reversed(self.__class__.__mro__):
            if hasattr(cls, "contribute_to_dict"):
                provided.update(cls.contribute_to_dict(self))
        if keys:
            data_dict.update(
                {
                    key: provided.get(key, defaults.get(key, None))
                    for key in keys
                }
            )
        else:
            data_dict.update(provided)
        return data_dict

    def __init__(self, *, itype: str | None = None):
        """
        Initialize the common instruction state.

        :param itype: Optional implementation type. Subclasses typically derive
            this from their content if not provided explicitly.
        """
        self._sort_key = None
        self._itype = itype
        self._obj_id = self._get_obj_id()
        self._protected = True

    def __init_subclass__(cls, ftype: str):
        """
        Register the functional type of a concrete instruction subclass.

        :param ftype: Functional type segment to append to the parent class
            ``ftype``.
        """
        ftype = ftype.replace(".", ":")
        cls._obj_id_count = 0
        cls._ftype += f".{ftype}"

    def __enter__(self) -> Instruction:
        """
        Temporarily disable write protection for context-managed mutation.

        :returns: ``self`` so the instruction can be modified inside a
            ``with`` block.
        """
        self._protected = False
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        """
        Re-enable write protection after a context-managed mutation block.

        :param exc_type: Exception type raised inside the context, if any.
        :param exc_val: Exception instance raised inside the context, if any.
        :param exc_tb: Traceback raised inside the context, if any.
        """
        self._protected = True

    def checksum_payload(self) -> int:
        """
        Return the payload used to identify logically identical instructions.

        :returns: Hashable payload representing the generic instruction state.
        """
        return (
            type(self).__module__,
            type(self).__qualname__,
            self._itype,
            self._ftype,
        )

    def checksum(self) -> int:
        """
        Return the hash-based checksum of the instruction.

        :returns: Integer checksum generated from :meth:`checksum_payload`.
        """
        return self._instruction_hash(self.checksum_payload())

    def record_payload(self, *, detailed: bool = False) -> dict[str, Any]:
        """
        Return a JSON-friendly record for manifests and debugging.

        :param detailed: If ``True``, include nested or parameter detail when
            available.
        :returns: Dictionary describing the instruction node.
        """
        return {
            "class": f"{type(self).__module__}.{type(self).__qualname__}",
            "ftype": self.ftype,
            "itype": self.itype,
        }

    @property
    def identifier(self) -> str:
        """
        Return the unique identifier of this instruction instance.

        The identifier is composed from the class ``ftype`` and a monotonically
        increasing per-class counter.

        :returns: Stable instance identifier.
        """
        return self._obj_id

    @property
    def instructions(self) -> Iterator[Instruction]:
        """
        Yield the instruction itself.

        Leaf-like instructions expose themselves as a single-item iterable so
        callers can treat all instruction nodes uniformly.
        """
        yield self

    # pylint: disable=unused-argument
    def unpack(
        self, environment: InstructionEnvironment | None = None
    ) -> Iterator[Instruction]:
        """
        Yield the fully environment-applied leaf instructions below this node.

        :param environment: Optional starting environment. If omitted, an empty
            :class:`InstructionEnvironment` is used.
        :returns: Iterator over leaf instructions after environment fusion.
        """
        if environment is None:
            environment = InstructionEnvironment()
        for _, is_leaf, ref, ref_env in self.walk(
            recursive=True,
            environment=environment,
            include_control=False,
        ):
            assert is_leaf
            yield ref.apply_environment(ref_env)

    def walk(
        self,
        environment: InstructionEnvironment | None = None,
        recursive: bool | int = True,
        include_control: bool = True,
        level: int = 0,
    ):
        """
        Traverse the instruction tree.

        :param environment: Optional starting environment.
        :param recursive: Recursion mode. ``True`` means unlimited recursion,
            ``False`` means one level, and integers specify an explicit depth.
        :param include_control: If ``True``, yield container/control nodes in
            addition to leaf instructions.
        :param level: Current nesting level used while recursing.
        :returns: Iterator yielding ``(level, is_leaf, instruction,
            environment)`` tuples.
        """
        raise NotImplementedError("subclass must implement this method")

    # pylint: enable=unused-argument

    def contribute_to_dict(self) -> Dict[str, Any]:
        """
        Return this class' contribution to :meth:`to_dict`.

        :returns: Dictionary describing the generic instruction state.
        """
        return {
            "identifier": self.identifier,
            "ftype": self.ftype,
            "itype": self.itype,
            "size": len(self),
        }

    @property
    def itype(self):
        """access read-only attribute itype"""
        return self._itype

    @property
    def ftype(self):
        """property for class level ftype attribute"""
        return type(self)._ftype

    @property
    def sort_key(self):
        """access protected sort key attribute"""
        if self._sort_key is None:
            self._sort_key = self._get_sort_key()
        return self._sort_key

    def update_sort_key(self, function: Callable[[Instruction], Any] | None = None) -> None:
        """
        Recompute the cached sort key.

        :param function: Optional sort-key function. If omitted, the class'
            default sort key is used.
        """
        self._sort_key = self._get_sort_key(function=function)

    def _get_default_sort_key(self) -> tuple:
        """Return the default sort key for this instruction."""
        return tuple()

    def _get_sort_key(
        self, function: Callable[[Instruction], Any] | None = None
    ) -> Any:
        """
        Build the sort key used by :attr:`sort_key`.

        :param function: Optional sort-key function. If omitted, the class'
            default implementation is used.
        :returns: Sort key object.
        """
        if function is None:
            return self._get_default_sort_key()
        return function(self)

    def is_subtype(self, itype: str | Instruction) -> bool:
        """
        Check whether this instruction's ``itype`` is compatible with another.

        :param itype: Reference implementation type, either as a string or as
            another instruction.
        :returns: ``True`` if this instruction is equal to or more specific than
            the requested ``itype``.
        """
        if isinstance(itype, Instruction):
            itype = itype.itype
        overlap = segment_overlap(*[self.itype.split("."), itype.split(".")])
        return overlap == itype.split(".")

    def __gt__(self, other):
        return self.itype > other.itype

    def __eq__(self, other):
        return self.itype == other.itype

    def __deepcopy__(self, memo: dict[int, weakref.ReferenceType] | None = None):
        """Implement subclass-specific deep-copy support."""
        raise NotImplementedError("subclasses must implement this method")

    def deepcopy(
        self, memo: dict[int, weakref.ReferenceType] | None = None
    ) -> Instruction:
        """
        Create a deep copy of the instruction tree.

        :param memo: Optional memoization dictionary using weak references to
            preserve shared structure during copying.
        :returns: Deep copy of the instruction.
        """
        if memo is None:
            memo = {}
        # keep the linter happy...
        # pylint: disable=unnecessary-dunder-call
        return self.__deepcopy__(memo=memo)
        # pylint: enable=unnecessary-dunder-call

    def apply_environment(
        self,
        environment: InstructionEnvironment,
        memo: dict | None = None,
    ) -> Instruction:
        """
        Apply an environment to the instruction.

        :param environment: Environment to fuse into the instruction.
        :param memo: Optional memoization dictionary used by subclasses.
        :returns: New instruction with the environment applied.
        """
        raise NotImplementedError("Must be implemented in subclass")

