    #     return env_applied

    def get_instruction_variables(self) -> Iterator[InstructionVariable]:
        """
        Yield the :class:`InstructionVariable` objects referenced by this node.

        Subclasses override this when they store instruction variables directly.
        The base implementation yields no variables.
        """
        return
        yield

    @classmethod
    def class_identifier(cls) -> str:
        """
        Return the functional type identifier of the class.

        :returns: Class-level ``ftype`` string.
        """
        return cls._ftype

    def as_type(self, other_class: type[Instruction]) -> Instruction:
        """
        Rebuild the instruction as another compatible instruction class.

        :param other_class: Target instruction class. ``self`` must already be
            an instance of that class or one of its subclasses.
        :returns: Reconstructed instruction of ``other_class``.
        :raises TypeError: If the conversion is not type-safe.
        """
        if not isinstance(self, other_class):
            raise TypeError(
                f"Cannot convert {self.__class__.__name__} to {other_class.__name__}"
            )
        return other_class.from_dict(self.to_dict())


