class GenericInstruction(Instruction, ftype="generic"):
    """Instruction implementation backed by a free-form parameter mapping.

    Generic instructions are the common storage layer used by leaf
    instructions. Parameters are stored by name and may contain instruction
    variables, scalars, or other backend-neutral metadata.
    """

    # _alias: dict[str, str] = {}

    def __init__(self, itype: str | None = None, **params: Any):
        """
        Initialize a generic instruction.

        :param itype: Optional implementation type. Defaults to the class
            ``ftype`` when omitted.
        :param params: Arbitrary instruction parameters stored verbatim.
        """
        if itype is None:
            itype = self.ftype
        super().__init__(itype=itype)
        # itype of generic instructions is by default the ftype
        self._params = params

    def __gt__(self, other):
        return self.sort_key > other.sort_key

    def __eq__(self, other):
        return self.sort_key == other.sort_key

    def _get_default_sort_key(self):
        return tuple(self.values())

    def keys(self) -> Iterator[str]:
        """Yield the parameter keys stored on the instruction."""
        yield from self._params.keys()

    def items(self) -> Iterator[tuple[str, Any]]:
        """Yield ``(key, value)`` pairs from the parameter mapping."""
        yield from self._params.items()

    def values(self) -> Iterator[Any]:
        """Yield the parameter values stored on the instruction."""
        yield from self._params.values()

    def __getitem__(self, key: str) -> Any:
        """Return a parameter by key."""
        if key in self._params:
            return self._params[key]
        raise KeyError(f"Key '{key}' not found in instruction parameters")
        # return self._from_alias(key)

    def __setitem__(self, key, value):
        self.set(key, value)

    # @classmethod
    # def set_alias(cls, alias, reference):
    #     """add an alias to the class"""
    #     cls._alias[alias] = reference

    def checksum_payload(self):
        """Extend the base checksum payload with the instruction parameters."""
        test_tuple = (
            *super().checksum_payload(),
            tuple(self.params),
        )
        return test_tuple

    def record_payload(self, *, detailed: bool = False) -> dict[str, Any]:
        """Return a record including the stored parameter mapping."""
        payload = super().record_payload(detailed=detailed)
        payload["params"] = stable_normalize(self._params)
        return payload

    @property
    def params(self) -> tuple[Any, ...]:
        """Return the stored parameter values as an immutable tuple."""
        return tuple(self.values())

    def get(self, *in_args: Any) -> Any:
        """
        Return a parameter value with optional default handling.

        :param in_args: ``(key,)`` or ``(key, default)`` exactly, mirroring
            :meth:`dict.get`.
        :returns: Stored value or the provided default.
        :raises KeyError: If the key is missing and no default is provided.
        :raises ValueError: If more than one default is supplied.
        """
        key, *default = in_args
        # if key in type(self)._alias:
        #     return self._from_alias(key)
        if key in self._params:
            return self._params[key]
        if len(default) == 0:
            raise KeyError(f"Key '{key}' not found in instruction parameters")
        if len(default) == 1:
            return default[0]
        raise ValueError(
            "get requires a key and an optional default value to return"
        )

    def set(self, key: str, value: Any) -> None:
        """
        Set a parameter value while honoring write protection.

        :param key: Parameter name to update.
        :param value: New parameter value.
        :raises ValueError: If the instruction is currently write-protected.
        """
        if self._protected:
            raise ValueError(
                f"cannot access protected value of key '{key}' for writing"
            )
        self._params[key] = value

    def contribute_to_dict(self):
        """Return the stored parameter mapping for :meth:`to_dict`."""
        # mapped_alias = {
        #     alias: self._params[target]
        #     for alias, target in type(self)._alias.items()
        # }
        return {**self._params}  # , **mapped_alias}

    def to_tuple(
        self, *keys: str, defaults: dict[str, Any] | None = None
    ) -> tuple[Any, ...]:
        """
        Return selected parameter values as a tuple.

        :param keys: Optional subset of keys. If omitted, all stored parameters
            are returned in iteration order.
        :param defaults: Optional mapping of fallback values for missing keys.
        :returns: Tuple of parameter values.
        """
        if defaults is None:
            defaults = {}
        # check params first, then check defaults, return None for miss
        if keys:
            return tuple(
                self.get(key, defaults.get(key, None)) for key in keys
            )
        return tuple(
            self.get(key, defaults.get(key, None)) for key in self.keys()
        )

    def __deepcopy__(
        self, memo: dict[int, weakref.ReferenceType] | None = None
    ) -> Instruction:
        """Return a deep copy of the generic instruction."""
        if memo is None:
            memo = {}
        if id(self) in memo:
            return memo[id(self)]()  # beware, must be called due to weakref
        copied = type(self).from_dict(self._params)
        memo[id(self)] = weakref.ref(copied)
        return copied

    @classmethod
    def from_dict(cls, params: dict[str, Any]) -> Instruction:
        """
        Reconstruct an instruction instance from a parameter dictionary.

        :param params: Serialized parameter mapping.
        :returns: New instruction instance of ``cls``.
        """
        return cls(**params)

    def walk(
        self,
        environment=None,
        recursive: bool | int = True,
        include_control=True,
        level=0,
    ):
        """
        Yield the generic instruction as a leaf node.

        :param environment: Optional active environment.
        :param recursive: Recursion mode used by the traversal API.
        :param include_control: Included for API compatibility; generic
            instructions are always yielded as leaves.
        :param level: Current traversal depth.
        :returns: Iterator yielding a single leaf tuple.
        """
        recursions = _interpret_recursive(recursive)
        if not recursions:
            return
        if environment is None:
            environment = InstructionEnvironment()
        yield level, True, self, environment

    def apply_environment(
        self,
        environment: InstructionEnvironment,
    ) -> Instruction:
        """
        Apply an instruction environment to all variable-valued parameters.

        :param environment: Environment whose variable mappings should be fused
            into the stored parameters.
        :returns: New instruction with transformed parameters.
        """
        modified_params = {}
        for key, val in self._params.items():
            if isinstance(val, InstructionVariable):
                if val.__class__ in environment:
                    modified_params[key] = environment[val.__class__].fuse(val)
                else:
                    modified_params[key] = val
            else:
                modified_params[key] = val
        return type(self).from_dict(modified_params)


