# LEAF INSTRUCTION
# ================


class LeafInstruction(GenericInstruction, ftype="leaf"):
    """
    Represents a Call or and Assignment.
    Leaf Instructions are exclusively defined via the keyword arguments
    listed in _DEFINING_KEYS. Positional args are not allowed.
    """

    _DEFINING_KEYS = []
    # _GENERAL_KEYS = ["inplace_add"]

    def __init__(
        self,
        *args: Any,
        itype: str | None = None,
        **kwargs: Any,
    ):
        """
        Initialize a leaf instruction from keyword-only defining parameters.

        :param args: Positional arguments are rejected to keep leaf
            instructions declarative.
        :param itype: Optional implementation type. Defaults to the class
            ``ftype``.
        :param kwargs: Defining parameter values for the leaf instruction.
        """
        if args:
            raise ValueError(
                "Positional arguments are not allowed in LeafInstruction"
            )
        if itype is None:
            itype = self.ftype
        super().__init__(
            **kwargs,
            itype=itype,
            # inplace_add=inplace_add,
        )

    def __init_subclass__(
        cls, ftype: str, defining_keys: Iterable[str] | None = None
    ):
        """
        Register the leaf subclass and its defining keys.

        :param ftype: Functional type suffix of the subclass.
        :param defining_keys: Keys required to reconstruct the instruction from
            its serialized form.
        """
        if defining_keys is None:
            defining_keys = cls._DEFINING_KEYS
        super().__init_subclass__(ftype=ftype)
        cls._DEFINING_KEYS = list(defining_keys)

    @classmethod
    def from_dict(cls, params: dict[str, Any]) -> Instruction:
        """
        Reconstruct the leaf instruction using its defining keys only.

        :param params: Serialized parameter mapping.
        :returns: New instruction instance of ``cls``.
        """
        return cls(
            **{key: params[key] for key in cls.get_generating_keys()},
        )

    @classmethod
    def get_generating_keys(cls) -> Iterator[str]:
        """
        Yield the keys required to recreate the leaf instruction.

        :returns: Iterator over defining parameter names.
        """
        yield from cls._DEFINING_KEYS
        # yield from cls._GENERAL_KEYS


