# GROUP PARENT CLASS
# ==================

from types import GeneratorType


class InstructionGroup(Instruction, ftype="group"):
    """Ordered collection of child instructions.

    Groups preserve instruction order while exposing convenience helpers for
    sorting, regrouping, flattening, and environment propagation.
    """

    # TODO
    # I consider an allow_parallel keyword, that enables or disables the
    # parallel execution of content.

    # Is it required?
    # Operations that enforce an order should maybe be executed in separate
    # subroutines.

    # Is it transferable?
    # Will an operation, that should be parallelized on a gpu will be properly
    # parallelized on a cpu, where blocks might be better?

    # Is it useful?
    # Most definitely, as we have some say in the later code design.

    # How would I do it?
    # Right now I think of parallelization levels, that can be chosen and even
    # varied in the implementation step. A single operation parallelization
    # could have a higher level, that we only enable on GPUs.

    def __init__(
        self,
        instructions: Iterable[Instruction | list[Instruction] | GeneratorType],
        itype: str | None = None,
    ):
        """
        Initialize a group from instructions or nested iterables.

        :param instructions: Iterable of instructions. Nested lists or
            generators are wrapped into nested :class:`InstructionGroup`
            instances.
        :param itype: Optional explicit implementation type. If omitted, the
            common ``itype`` prefix of the children is used.
        """
        self._instructions = []
        for instr in instructions:
            if isinstance(instr, Instruction):
                self._instructions.append(instr)
            elif isinstance(instr, (list, GeneratorType)):
                self._instructions.append(InstructionGroup(instr))
            else:
                raise TypeError("Unsupported input to InstructionGroup")
        if itype is None:
            itype = InstructionGroup._get_itype_common_root(self._instructions)
        # self._loop_safe = loop_safe
        # self._loop_wrap = loop_wrap
        super().__init__(itype=itype)

    # @property
    # def loop_safe(self):
    #     """check if the group is safe to be wrapped by a loop"""
    #     return self._loop_safe

    # @property
    # def loop_wrap(self):
    #     """check if the group shall be wrapped in a loop capture, which will wrap it in a loop capture"""
    #     return self._loop_wrap

    def __len__(self) -> int:
        """Return the total logical size of all child instructions."""
        return sum(len(instr) for instr in self.instructions)

    def append(self, instruction: Instruction) -> None:
        """
        Append an instruction while preserving the group's ``itype`` contract.

        :param instruction: Instruction to append.
        :raises TypeError: If ``instruction`` is not an :class:`Instruction`.
        :raises ValueError: If the appended instruction is incompatible with the
            group's existing ``itype``.
        """
        if not isinstance(instruction, Instruction):
            raise TypeError("Can only append Instruction instances")
        if not self._instructions:
            self._instructions.append(instruction)
            self._itype = instruction.itype
            return
        if not instruction.is_subtype(self._itype):
            raise ValueError(
                "Appended instruction must match existing group itype"
            )
        self._instructions.append(instruction)

    def __deepcopy__(
        self, memo: dict[int, weakref.ReferenceType] | None = None
    ) -> Instruction:
        """Return a deep copy of the group and all nested instructions."""
        if memo is None:
            memo = {}
        if id(self) in memo:
            return memo[id(self)]()  # beware, must be called due to weakref
        copied_instructions = []
        for instr in self._instructions:
            if id(instr) in memo:
                copied_instr = memo[id(instr)]()
            else:
                copied_instr = instr.deepcopy(memo)
            copied_instructions.append(copied_instr)
        copied_group = type(self)(copied_instructions, itype=self.itype)
        memo[id(self)] = weakref.ref(copied_group)
        return copied_group

    def contribute_to_dict(self) -> dict[str, Any]:
        """Return the group's serialized child list."""
        return {"instructions": self._instructions}

    def record_payload(self, *, detailed: bool = False) -> dict[str, Any]:
        """Return a compact or expanded record for the instruction group."""
        payload = super().record_payload(detailed=detailed)
        payload["count"] = len(self._instructions)
        if detailed:
            payload["instructions"] = [
                instruction.record_payload(detailed=True)
                for instruction in self._instructions
            ]
        else:
            payload["children"] = [
                {
                    "class": f"{type(instruction).__module__}.{type(instruction).__qualname__}",
                    "ftype": instruction.ftype,
                    "itype": instruction.itype,
                }
                for instruction in self._instructions
            ]
        return payload

    @property
    def itype(self):
        return self._itype

    @property
    def instructions(self) -> Iterator[Instruction]:
        """Yield the group's child instructions in order."""
        yield from self._instructions

    def walk(
        self,
        environment=None,
        recursive: bool | int = True,
        include_control=True,
        level=0,
    ):
        """
        Traverse the group and optionally its descendants.

        :param environment: Optional starting environment.
        :param recursive: Recursion mode controlling how deeply children are
            traversed.
        :param include_control: If ``True``, include the group node itself.
        :param level: Current traversal depth.
        :returns: Iterator yielding traversal tuples.
        """
        recursions = _interpret_recursive(recursive)
        if not recursions:
            return
        if environment is None:
            environment = InstructionEnvironment()
        if include_control:
            yield level, False, self, environment
            for instr in self.instructions:
                # iterate level and recursion parameter as control structure itself has been yielded
                yield from instr.walk(
                    environment=environment,
                    recursive=_next_recursive(recursions),
                    include_control=include_control,
                    level=level + 1,
                )
        else:
            for instr in self.instructions:
                yield from instr.walk(
                    environment=environment,
                    recursive=recursions,
                    include_control=include_control,
                    level=level,
                )

    def flatten(self) -> InstructionGroup:
        """
        Return a new group with all nested control structure unpacked.

        :returns: Flattened instruction group built from :meth:`unpack`.
        """
        return type(self)(list(self.unpack()))

    def sorted(
        self,
        ordering_function: Callable[[Instruction], Any] | None = None,
        sort_function: Callable[[Iterable[Any]], list[Any]] | None = None,
    ) -> InstructionGroup:
        """
        Return a sorted copy of the group.

        :param ordering_function: Optional key function. When omitted, the
            child instructions' native ordering is used.
        :param sort_function: Optional sorting function, defaulting to
            :func:`sorted`.
        :returns: New sorted instruction group.
        """
        if sort_function is None:
            sort_function = sorted
        if ordering_function is None:
            return type(self)(
                list(sort_function(self.instructions)), itype=self._itype
            )
        sorted_instructions = sort_function(
            [(ordering_function(instr), instr) for instr in self.instructions]
        )
        return type(self)(
            [instr for _, instr in sorted_instructions], itype=self._itype
        )

    def grouped(
        self,
        function: Callable[[Instruction], Any] | None = None,
        size: int | None = None,
        number: int | None = None,
    ) -> InstructionGroup:
        """
        Partition the group using one grouping strategy.

        :param function: Optional grouping key function.
        :param size: Optional maximum subgroup size.
        :param number: Optional number of output batches.
        :returns: Group containing subgroup instructions.
        :raises ValueError: If more than one grouping mode is requested.
        """

        match (function, size, number):
            case (function, None, None):
                assert callable(function)
                return self.grouped_by_key(function)

            case (None, size, None):
                assert isinstance(size, int)
                return self.grouped_to_size(size)

            case (None, None, number):
                assert isinstance(number, int)
                return self.grouped_to_batches(number)

            case _:
                raise ValueError(
                    "only one of 'function', 'size' and 'number' can be set"
                )

    def grouped_by_key(
        self,
        function: Callable[[Instruction], Any],
        group_type: type[InstructionGroup] | None = None,
        subgroup_type: type[InstructionGroup] | None = None,
    ) -> InstructionGroup:
        """
        Group instructions by a user-provided key.

        :param function: Key function applied to each child instruction.
        :param group_type: Optional outer group class.
        :param subgroup_type: Optional subgroup class.
        :returns: Group of grouped instructions.
        """
        groups: Dict[Any, List[Instruction]] = {}
        for instr in self.instructions:
            group_id = function(instr)
            if group_id not in groups:
                groups[group_id] = []
            groups[group_id].append(instr)
        if group_type is None:
            group_type = type(self)
        if subgroup_type is None:
            subgroup_type = type(self)
        return group_type(
            [
                subgroup_type(group, itype=self._itype)
                for group in groups.values()
            ],
            itype=self._itype,
        )

    def grouped_to_batches(
        self,
        batches: int,
        group_type: type[InstructionGroup] | None = None,
        subgroup_type: type[InstructionGroup] | None = None,
    ) -> InstructionGroup:
        """
        Partition instructions into round-robin batches.

        :param batches: Number of output batches.
        :param group_type: Optional outer group class.
        :param subgroup_type: Optional subgroup class.
        :returns: Group containing the batches.
        """
        groups: List[List[Instruction]] = [[] for _ in range(batches)]
        if group_type is None:
            group_type = type(self)
        if subgroup_type is None:
            subgroup_type = type(self)
        for num, instr in enumerate(self.instructions):
            groups[num % batches].append(instr)
        return group_type(
            [subgroup_type(group) for group in groups], itype=self._itype
        )

    def grouped_to_size(
        self,
        max_size: int,
        group_type: type[InstructionGroup] | None = None,
        subgroup_type: type[InstructionGroup] | None = None,
    ) -> InstructionGroup:
        """
        Partition instructions into consecutive fixed-size groups.

        :param max_size: Maximum number of instructions per subgroup.
        :param group_type: Optional outer group class.
        :param subgroup_type: Optional subgroup class.
        :returns: Group containing the size-limited subgroups.
        """
        group: List[Instruction] = []
        collect: List[List[Instruction]] = []
        if group_type is None:
            group_type = type(self)
        if subgroup_type is None:
            subgroup_type = type(self)
        for instr in self.instructions:
            if len(group) >= max_size:
                collect.append(subgroup_type(group, itype=self._itype))
                group = []
            group.append(instr)
        if group:
            collect.append(subgroup_type(group, itype=self._itype))
        return group_type(collect, itype=self._itype)

    def apply_environment(
        self, environment: InstructionEnvironment
    ) -> Instruction:
        """
        Apply one environment to every child instruction.

        :param environment: Environment to fuse into the entire group.
        :returns: New group whose children have the environment applied.
        """
        return type(self)(
            [
                instr.apply_environment(environment)
                for instr in self.instructions
            ],
            itype=self.itype,
        )


class ParametricInstructionGroup(InstructionGroup, ftype="pgroup"):
    """
    Within this group, all instructions must be of the same type.
    So far I will not allow any internal groups, only leaf instructions.
    """

    def __init__(
        self,
        instructions: Iterable[Instruction],
        generating_instruction_class: type[LeafInstruction] | None = None,
    ):
        """
        Initialize a group whose children all share one leaf instruction type.

        :param instructions: Leaf instructions to normalize into one class.
        :param generating_instruction_class: Explicit leaf class to use for all
            children. When omitted, the first instruction determines the class.
        """
        if generating_instruction_class is None:
            for instruction in instructions:
                if generating_instruction_class is None:
                    generating_instruction_class = type(instruction)
                if not isinstance(instruction, generating_instruction_class):
                    raise TypeError(
                        "ParametricGroup can only contain instructions of the same type,"
                        + " or type must be given as argument"
                    )
        if not issubclass(generating_instruction_class, LeafInstruction):
            raise TypeError(
                "generating instruction class must be a leaf class"
            )
        super().__init__(
            [
                instruction.as_type(generating_instruction_class)
                for instruction in instructions
            ],
            itype=generating_instruction_class._ftype,
        )
        self._gen_instr_class = generating_instruction_class

    def generate_instruction(self, *args: Any, **kwargs: Any) -> LeafInstruction:
        """
        Create a new instruction using the group's generating class.

        :param args: Positional arguments forwarded to the generating class.
        :param kwargs: Keyword arguments forwarded to the generating class.
        :returns: Newly constructed leaf instruction.
        """
        return self._gen_instr_class(*args, **kwargs)

    def get_generating_keys(self) -> Iterator[str]:
        """Yield the defining keys of the generating instruction class."""
        yield from self._gen_instr_class.get_generating_keys()

    def iterate_parameters(self) -> Iterator[dict[str, Any]]:
        """
        Yield serialized parameter dictionaries for all child instructions.

        :returns: Iterator over per-instruction parameter mappings.
        """
        for instruction in self.instructions:
            yield instruction.to_dict(*self.get_generating_keys())

    def grouped_by_key(self, function, subgroup_type=None):
        return super().grouped_by_key(
            function, group_type=InstructionGroup, subgroup_type=subgroup_type
        )

    def grouped_to_batches(self, batches, subgroup_type=None):
        return super().grouped_to_batches(
            batches, group_type=InstructionGroup, subgroup_type=subgroup_type
        )

    def grouped_to_size(self, max_size, subgroup_type=None):
        return super().grouped_to_size(
            max_size, group_type=InstructionGroup, subgroup_type=subgroup_type
        )


