class ContentInstruction(Instruction, ftype="content"):
    """Instruction wrapper that owns exactly one nested instruction."""

    def __init__(self, content: Instruction, itype: str | None = None):
        """
        Initialize a content-bearing instruction.

        :param content: Nested instruction wrapped by this node.
        :param itype: Optional explicit implementation type. Defaults to the
            nested instruction's ``itype``.
        """
        if itype is None:
            itype = content.itype
        super().__init__(itype=itype)
        if not isinstance(content, Instruction):
            raise TypeError(
                "content of environment must be of type instruction"
            )
        self._content = content

    def contribute_to_dict(self) -> dict[str, Any]:
        """Return the wrapped content for serialization."""
        return {"content": self._content}

    def __len__(self) -> int:
        """Return the logical size of the wrapped instruction."""
        return len(self._content)

    @property
    def instructions(self) -> Iterator[Instruction]:
        """Yield the wrapped instruction."""
        yield self._content

    @property
    def content(self) -> Instruction:
        """Return the wrapped instruction."""
        return self._content

    def __deepcopy__(
        self, memo: dict[int, weakref.ReferenceType] | None = None, **kwargs: Any
    ) -> Instruction:
        """Return a deep copy of the wrapper and its nested content."""
        if memo is None:
            memo = {}
        copied_content = self.content.deepcopy(memo=memo, **kwargs)
        return type(self)(
            copied_content,
            itype=self.itype,
            **kwargs,
        )

    def walk(
        self,
        environment=None,
        recursive: bool | int = True,
        include_control=True,
        level=0,
    ):
        """
        Traverse the wrapped content.

        :param environment: Optional starting environment.
        :param recursive: Recursion mode controlling nested traversal depth.
        :param include_control: If ``True``, include the wrapper itself before
            traversing the nested instruction.
        :param level: Current traversal depth.
        :returns: Iterator yielding traversal tuples.
        """
        # an environment does not count as recursive step!!
        recursions = _interpret_recursive(recursive)
        if not recursions:
            return
        if environment is None:
            environment = InstructionEnvironment()
        if include_control:
            yield level, False, self, environment
            for instr in self.instructions:
                # iterate level and recursion parameter, as control structure itself has been yielded
                yield from instr.walk(
                    environment=environment,
                    recursive=_next_recursive(recursions),
                    include_control=include_control,
                    level=level + 1,
                )
        else:
            for instr in self.instructions:
                yield from instr.walk(
                    environment=environment,
                    recursive=recursions,
                    include_control=include_control,
                    level=level,
                )

    def apply_environment(
        self, environment: InstructionEnvironment, **kwargs
    ) -> Instruction:
        """
        Apply an environment to the wrapped content and rebuild the wrapper.

        :param environment: Environment to fuse into the nested instruction.
        :param kwargs: Extra constructor arguments forwarded while rebuilding.
        :returns: New wrapper containing the transformed content.
        """
        return type(self)(
            self.content.apply_environment(environment),
            **kwargs,
        )

    def record_payload(self, *, detailed: bool = False) -> dict[str, Any]:
        """Return a compact or expanded record for wrapped content."""
        payload = super().record_payload(detailed=detailed)
        if detailed:
            payload["content"] = self.content.record_payload(detailed=True)
        else:
            payload["content"] = {
                "class": f"{type(self.content).__module__}.{type(self.content).__qualname__}",
                "ftype": self.content.ftype,
                "itype": self.content.itype,
            }
        return payload


