class EnvironmentInstruction(ContentInstruction, ftype="environment"):
    """Wrapper that associates a nested instruction with an environment."""

    def __init__(
        self,
        content: Instruction,
        *,
        environment: InstructionEnvironment,
        itype: str | None = None,
    ):
        """
        Initialize an environment wrapper.

        :param content: Nested instruction to execute in the environment.
        :param environment: Environment providing variable substitutions or
            offsets.
        :param itype: Optional explicit implementation type.
        """
        super().__init__(content, itype=itype)
        self._environment = environment

    @property
    def environment(self) -> InstructionEnvironment:
        """Return the environment stored on this wrapper."""
        return self._environment

    def contribute_to_dict(self) -> dict[str, Any]:
        """Return the stored environment for serialization."""
        return {"environment": self.environment}

    def record_payload(self, *, detailed: bool = False) -> dict[str, Any]:
        """Return a record for an environment wrapper."""
        payload = super().record_payload(detailed=detailed)
        if detailed:
            payload["environment"] = stable_normalize(dict(self.environment))
        else:
            payload["environment_size"] = len(self.environment)
        return payload

    def __deepcopy__(
        self, memo: dict[int, weakref.ReferenceType] | None = None, **kwargs: Any
    ) -> Instruction:
        """Return a deep copy of the environment wrapper."""
        if memo is None:
            memo = {}
        return super().__deepcopy__(
            memo=memo,
            environment={
                key: (
                    val.deepcopy(memo=memo)
                    if isinstance(val, Instruction)
                    else val
                )
                for key, val in self.environment.items()
            },
            **kwargs,
        )

    def apply_environment(
        self, environment: InstructionEnvironment, **kwargs
    ) -> Instruction:
        """
        Fuse an outer environment into this wrapper's local environment.

        :param environment: Outer environment to combine with this wrapper.
        :param kwargs: Extra constructor arguments forwarded while rebuilding.
        :returns: Content instruction with the combined environment applied.
        """
        combined_environment = environment.fuse(self.environment)
        return self.content.apply_environment(combined_environment, **kwargs)

    def walk(
        self,
        environment=None,
        recursive: bool | int = True,
        include_control=True,
        level=0,
    ):
        """
        Traverse the wrapped content using the combined active environment.

        :param environment: Optional incoming environment.
        :param recursive: Recursion mode controlling nested traversal depth.
        :param include_control: If ``True``, include the environment node.
        :param level: Current traversal depth.
        :returns: Iterator yielding traversal tuples.
        """

        recursions = _interpret_recursive(recursive)
        if not recursions:
            return
        if environment is None:
            environment = InstructionEnvironment()
        combined_environment = environment.fuse(self.environment)
        if include_control:
            yield level, False, self, environment
            for instr in self.instructions:
                # iterate level and recursion parameter, as control structure itself has been yielded
                yield from instr.walk(
                    environment=combined_environment,
                    recursive=_next_recursive(recursions),
                    include_control=include_control,
                    level=level + 1,
                )
        else:
            for instr in self.instructions:
                yield from instr.walk(
                    environment=combined_environment,
                    recursive=recursions,
                    include_control=include_control,
                    level=level,
                )


