# ==================


class OffsetEnvironmentInstruction(EnvironmentInstruction, ftype="offset"):
    """
    Within this environment, variables are offsetted
    """

    # TODO
    # Unpack (and therefore indirectly flatten) needs to consider offsets!

    # Contains
    # - Instructions to be offsetted

    # requires:
    # - value of offset
    # - variable mapping if names change

    def __init__(
        self,
        content: Instruction,
        *,
        offsets: dict[type[InstructionVariable], InstructionVariable] | None = None,
        itype: str | None = None,
    ):
        """
        Initialize an offset-only environment.

        :param content: Nested instruction to execute with offsets applied.
        :param offsets: Optional mapping from inner variable classes to outer
            variables.
        :param itype: Optional explicit implementation type.
        """
        super().__init__(
            content, environment=InstructionEnvironment(), itype=itype
        )
        if offsets:
            for offset_target, offset_value in offsets.items():
                self.set_offset(offset_target, offset_value)

    def set_offset(
        self,
        inner_class: type[InstructionVariable],
        outer_variable: InstructionVariable,
    ) -> OffsetEnvironmentInstruction:
        """
        Register one variable offset mapping.

        :param inner_class: Instruction-variable class looked up inside the
            nested content.
        :param outer_variable: Variable providing the outer offset.
        :returns: ``self`` for call chaining.
        """
        if not isinstance(outer_variable, InstructionVariable):
            raise TypeError(
                "Outer variable must be of type InstructionVariable"
            )
        self.environment.update(inner_class, outer_variable)
        return self


