###############################################################################
#
# MAP APPLY
# =========


class MapApplyInstruction(ContentInstruction, ftype="map"):
    """
    Within this environment, Environment groups (e.g. OffsetGroups) are applied
    to an instructiongroup that is then executed from within every environment.
    """

    def __init__(
        self,
        content: Instruction,
        environments: Iterable[InstructionEnvironment],
        itype: str | None = None,
    ):
        """
        Initialize a map-apply wrapper.

        :param content: Instruction to execute for every supplied environment.
        :param environments: Iterable of environments to apply to ``content``.
        :param itype: Optional explicit implementation type.
        """
        super().__init__(content, itype=itype)
        self._environments = list(environments)

    @property
    def environments(self) -> Iterator[InstructionEnvironment]:
        """Yield the environments applied by the map instruction."""
        yield from self._environments

    def contribute_to_dict(self) -> dict[str, Any]:
        """Return the stored environments for serialization."""
        return {"environments": self._environments}

    def record_payload(self, *, detailed: bool = False) -> dict[str, Any]:
        """Return a compact or expanded record for map-apply content."""
        payload = super().record_payload(detailed=detailed)
        payload["environment_count"] = len(self._environments)
        if detailed:
            payload["environments"] = [
                stable_normalize(dict(environment))
                for environment in self._environments
            ]
        return payload

    def __len__(self) -> int:
        """Return the flattened logical size across all environments."""
        return len(self._content) * len(self._environments)

    def __deepcopy__(
        self, memo: dict[int, weakref.ReferenceType] | None = None, **kwargs: Any
    ) -> Instruction:
        """Return a deep copy of the map instruction and all environments."""
        if memo is None:
            memo = {}
        copied_content = self.content.deepcopy(memo=memo, **kwargs)
        return type(self)(
            copied_content,
            itype=self.itype,
            environments=[
                environment.deepcopy(memo=memo, **kwargs)
                for environment in self.environments
            ],
            **kwargs,
        )

    def walk(
        self,
        environment=None,
        recursive: bool | int = True,
        include_control=True,
        level=0,
    ):
        """
        Traverse the mapped content once for every stored environment.

        :param environment: Optional incoming environment.
        :param recursive: Recursion mode controlling nested traversal depth.
        :param include_control: If ``True``, include the map instruction node.
        :param level: Current traversal depth.
        :returns: Iterator yielding traversal tuples.
        """

        recursions = _interpret_recursive(recursive)
        if not recursions:
            return
        if environment is None:
            environment = InstructionEnvironment()
        if include_control:
            yield level, False, self, environment
            for thisenv in self.environments:
                combined_environment = environment.fuse(thisenv)
                for instr in self.instructions:
                    # iterate level and recursion parameter, as control structure itself has been yielded
                    yield from instr.walk(
                        environment=combined_environment,
                        recursive=_next_recursive(recursions),
                        include_control=include_control,
                        level=level + 1,
                    )
        else:
            for thisenv in self.environments:
                combined_environment = environment.fuse(thisenv)
                for instr in self.instructions:
                    yield from instr.walk(
                        environment=combined_environment,
                        recursive=recursions,
                        include_control=include_control,
                        level=level,
                    )

    def flatten(self) -> InstructionGroup:
        """
        Expand the map instruction into a flat instruction group.

        :returns: Group containing one unpacked content expansion per
            environment.
        """
        return InstructionGroup(
            sum(
                (
                    list(self.content.unpack(environment=env))
                    for env in self.environments
                ),
                start=[],
            ),
        )

        # return InstructionGroup(
        #     [self.content.apply_environment(env) for env in self.environments]
        # )

    def apply_environment(
        self,
        environment: InstructionEnvironment,
        **kwargs,
    ) -> Instruction:
        """
        Apply an outer environment to each stored map environment.

        :param environment: Environment fused into each stored environment.
        :param kwargs: Extra constructor arguments forwarded while rebuilding.
        :returns: Group containing the environment-applied content instances.
        """
        return InstructionGroup(
            [
                self.content.apply_environment(environment.fuse(env), **kwargs)
                for env in self.environments
            ]
        )


###############################################################################
#
# VARIATION
# =========


class VariationInstruction(ContentInstruction, ftype="variation"):
    """
    A variation is a special kind of offset that implies, that data contains copies
    that are addressable via offsets and independent and non-overlapping. E.g. a state
    operator interacts with several different sets of dynamic, but these different
    versions do not interact anywhere, implying some wiggle room for safe parallelization
    """

    def __init__(self, content: Instruction, key: str, itype: str | None = None):
        """
        Initialize a variation selector with one named variant.

        :param content: Initial active variation content.
        :param key: Name of the initial variation.
        :param itype: Optional explicit implementation type.
        """
        super().__init__(content, itype=itype)
        if not isinstance(key, str):
            raise KeyError("Key must be a string")
        self._variations = {key: content}

    def add_variation(self, key: str, variation: Instruction) -> None:
        """
        Register an additional selectable variation.

        :param key: Name of the variation.
        :param variation: Instruction used when the variation is selected.
        """
        if not isinstance(key, str):
            raise KeyError("Key must be a string")
        if not isinstance(variation, Instruction):
            raise TypeError("Variation must be of type instruction")
        self._variations[key] = variation

    def select(self, key: str) -> None:
        """
        Switch the active variation.

        :param key: Name of the variation to activate.
        """
        self._content = self._variations[key]


