class CallInstruction(
    LeafInstruction, ftype="call", defining_keys=["routine", "mapping"]
):
    """
    Leaf instruction representing a library-routine invocation.
    """

    def __init__(
        self,
        routine,
        mapping=None,
    ):
        """
        Initialize a call instruction.

        :param routine: Routine object to invoke when this instruction is
            lowered by a backend.
        :param mapping: Optional remapping dictionary used to translate the
            routine's definition-time instruction-variable assignments to
            assignments available at the call site.
        """
        merged_mapping = {}
        if mapping is not None:
            merged_mapping.update(
                self._normalize_mapping(routine, mapping)
            )
        super().__init__(
            routine=routine,
            mapping=merged_mapping,
            itype=self.ftype,
        )
        self._routine = routine
        self._mapping = merged_mapping

    @property
    def routine(self):
        """Return the routine referenced by the call instruction."""
        return self._routine

    @property
    def mapping(self):
        """Return the call-site assignment remapping."""
        return dict(self._mapping)

    @staticmethod
    def _expand_mapping_key(raw_key, routine):
        """Expand one mapping key to explicit assignment tuples."""
        assignments = [
            argument.assignment
            for argument in routine.get_arguments()
            if argument.assignment is not None
        ]
        if isinstance(raw_key, tuple) and len(raw_key) == 2:
            return [raw_key]
        matches = [
            assignment
            for assignment in assignments
            if assignment[0] == raw_key
        ]
        if matches:
            return matches
        raise TypeError(
            "call mapping keys must be assignment tuples or assignment sources "
            "present in the callee signature"
        )

    @staticmethod
    def _normalize_mapping_value(raw_value, *, key_assignment, allow_expand):
        """Normalize one mapping value to an explicit assignment tuple."""
        if isinstance(raw_value, tuple) and len(raw_value) == 2:
            return raw_value
        if allow_expand:
            return raw_value, key_assignment[1]
        raise TypeError(
            "call mapping values must be assignment tuples when one key maps "
            "to multiple callee assignments"
        )

    @classmethod
    def _normalize_mapping(cls, routine, mapping):
        """Canonicalize mappings to strict ``(source, key) -> (source, key)``."""
        normalized = {}
        for raw_key, raw_value in mapping.items():
            expanded_keys = cls._expand_mapping_key(raw_key, routine)
            for expanded_key in expanded_keys:
                normalized[expanded_key] = cls._normalize_mapping_value(
                    raw_value,
                    key_assignment=expanded_key,
                    allow_expand=not (
                        isinstance(raw_value, tuple) and len(raw_value) == 2
                    ),
                )
        return normalized


class ToZeroInstruction(
    LeafInstruction, ftype="tozero", defining_keys=["target"]
):
    """
    Leaf instruction requesting zero-initialization through a backend routine.
    """

    def __init__(self, target):
        """
        Initialize a reset instruction for a symbolic target variable.

        :param target: Instruction variable whose assigned routine-level
            components should be reset via a backend-provided helper routine.
        """
        if not (
            isinstance(target, InstructionVariable)
            or (
                isinstance(target, type)
                and issubclass(target, InstructionVariable)
            )
        ):
            raise TypeError(
                "ToZeroInstruction target must be an InstructionVariable"
            )
        super().__init__(
            target=target,
            itype=self.ftype,
        )
        self._target = target

    @property
    def target(self):
        """Return the symbolic target that should be zeroed."""
        return self._target


