class PolynomialInstruction(
    LeafInstruction,
    ftype="polynomial",
    defining_keys=["tgt0", "src0", "coeffs"],
):
    """Leaf instruction representing a polynomial update."""

    def __init__(
        self,
        tgt0: InstructionVariable,
        src0: InstructionVariable,
        coeffs: Iterable[Any],
        **more_args: Any,
    ):
        """
        Initialize a polynomial update instruction.

        :param tgt0: Target instruction variable.
        :param src0: Source instruction variable whose values are raised to
            increasing powers.
        :param coeffs: Polynomial coefficients ordered by ascending power.
        :param more_args: Additional leaf-instruction parameters.
        """
        assert isinstance(tgt0, InstructionVariable)
        assert isinstance(src0, InstructionVariable)
        super().__init__(
            tgt0=tgt0,
            src0=src0,
            coeffs=[InstructionScalar.convert(coeff) for coeff in coeffs],
            **more_args,
        )


